async (page) => {
  // 1. 공격 작전의 '코치에게' 버튼 클릭
  const dialog = page.locator('dialog');
  const attackGroup = dialog.locator('group, [role="group"]').filter({ hasText: '공격 작전' });
  await attackGroup.locator('button:has-text("코치에게")').click();

  // 2. 모달 내의 저장 버튼 클릭
  await dialog.locator('button:has-text("저장")').click();

  // 3. 메인의 경기 시작 버튼 클릭
  await page.locator('main button:has-text("경기 시작")').click();
}
